--
-- Name: fn_check_portfolio_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_check_portfolio_history(p_portfolio_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_bad RECORD;
BEGIN
    SELECT * INTO v_bad
    FROM fn_portfolio_history(p_portfolio_id) h
    WHERE h.cash_after < 0
       OR (h.ticker IS NOT NULL AND h.shares_after < 0)
    ORDER BY h.event_date, h.event_order, h.event_id
    LIMIT 1;

    IF NOT FOUND THEN
        RETURN;   -- history is valid
    END IF;

    -- A BUY or WITHDRAWAL can only lower cash; a SELL can only lower
    -- shares. So one event never breaks both rules.
    IF v_bad.cash_after < 0 THEN
        RAISE EXCEPTION 'Not enough cash: this change makes the cash balance negative'
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_cash_never_negative',
                  DETAIL     = format('Cash would be %s on %s, after %s.',
                                      v_bad.cash_after, v_bad.event_date, v_bad.event_label),
                  HINT       = 'Cash must be >= 0 at every point in the history '
                               '(same day: cash transactions before trades).';
    ELSE
        RAISE EXCEPTION 'Not enough shares: this change makes the % holding negative', v_bad.ticker
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_shares_never_negative',
                  DETAIL     = format('%s shares would be %s on %s, after %s.',
                                      v_bad.ticker, v_bad.shares_after,
                                      v_bad.event_date, v_bad.event_label),
                  HINT       = 'You cannot sell more shares than you hold at that date.';
    END IF;
END;
$$;


--
-- Name: fn_event_date_order(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_event_date_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_date        DATE;
    v_start_date  portfolio.start_date%TYPE;
    v_latest      DATE;
BEGIN
    -- IF, not CASE: NEW.trade_date doesn't exist on cash_transaction,
    -- and only the branch that runs is evaluated.
    IF TG_TABLE_NAME = 'trade' THEN
        v_date := NEW.trade_date;
    ELSE
        v_date := NEW.txn_date;
    END IF;

    -- Lock the portfolio row until COMMIT/ROLLBACK. A second
    -- transaction on the same portfolio waits here.
    SELECT start_date INTO v_start_date
    FROM portfolio
    WHERE portfolio_id = NEW.portfolio_id
    FOR UPDATE;

    -- Unknown portfolio: leave it to the FK
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF v_date < v_start_date THEN
        RAISE EXCEPTION 'Date % is before the portfolio start date', v_date
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_date_before_start',
                  DETAIL     = format('Portfolio %s starts on %s.', NEW.portfolio_id, v_start_date);
    END IF;

    -- GREATEST ignores NULLs (a portfolio with no events gives NULL,
    -- and "v_date < NULL" is NULL, so nothing is raised)
    SELECT GREATEST((SELECT max(trade_date) FROM trade
                     WHERE portfolio_id = NEW.portfolio_id),
                    (SELECT max(txn_date) FROM cash_transaction
                     WHERE portfolio_id = NEW.portfolio_id))
    INTO v_latest;

    IF v_date < v_latest THEN
        RAISE EXCEPTION 'Date % is before the latest event in this portfolio', v_date
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_date_before_latest',
                  DETAIL     = format('Latest event of portfolio %s is on %s.',
                                      NEW.portfolio_id, v_latest),
                  HINT       = 'Enter events in date order (the same date is allowed).';
    END IF;

    IF TG_TABLE_NAME = 'cash_transaction' AND v_date > CURRENT_DATE THEN
        RAISE EXCEPTION 'Cash transaction date % is in the future', v_date
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_cash_txn_future_date',
                  DETAIL     = format('Today is %s.', CURRENT_DATE);
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_holding_pl(integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_holding_pl(p_portfolio_id integer DEFAULT NULL::integer, p_as_of date DEFAULT NULL::date) RETURNS TABLE(portfolio_id integer, portfolio_name character varying, ticker character varying, shares_held bigint, avg_cost numeric, cost_basis numeric, close_date date, close numeric, market_value numeric, unrealized_pl numeric, realized_pl numeric, total_pl numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH params AS (
        SELECT COALESCE(p_as_of, CURRENT_DATE) AS as_of
    ),
    last_state AS (
        -- Position after the last trade on or before as_of, per ticker
        SELECT DISTINCT ON (p.portfolio_id, h.ticker)
               p.portfolio_id, p.portfolio_name, h.ticker,
               h.shares_after, h.avg_cost_after, h.realized_pl_total,
               CASE WHEN h.shares_after > 0
                    THEN ROUND(h.shares_after * h.avg_cost_after, 2) ELSE 0 END AS cost_basis
        FROM portfolio p
        CROSS JOIN params
        CROSS JOIN LATERAL fn_position_history(p.portfolio_id) h
        WHERE (p_portfolio_id IS NULL OR p.portfolio_id = p_portfolio_id)
          AND h.trade_date <= params.as_of
        ORDER BY p.portfolio_id, h.ticker, h.trade_seq DESC
    )
    SELECT ls.portfolio_id, ls.portfolio_name, ls.ticker,
           ls.shares_after,
           CASE WHEN ls.shares_after > 0 THEN ROUND(ls.avg_cost_after, 2) END,   -- NULL when closed
           ls.cost_basis,
           c.price_date,
           c.close,
           ls.shares_after * c.close                     AS market_value,
           ls.shares_after * c.close - ls.cost_basis     AS unrealized_pl,
           ROUND(ls.realized_pl_total, 2)                AS realized_pl,
           ls.shares_after * c.close - ls.cost_basis
             + ROUND(ls.realized_pl_total, 2)            AS total_pl
    FROM last_state ls
    CROSS JOIN params
    -- Latest close on or before as_of (primary key index). A traded ticker
    -- always has one, because it was traded on a priced day <= as_of.
    CROSS JOIN LATERAL (
        SELECT dp.price_date, dp.close FROM daily_price dp
        WHERE dp.ticker = ls.ticker AND dp.price_date <= params.as_of
        ORDER BY dp.price_date DESC
        LIMIT 1
    ) c
    ORDER BY ls.portfolio_id, ls.ticker;
$$;


--
-- Name: fn_monthly_returns(integer, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_monthly_returns(p_portfolio_id integer DEFAULT NULL::integer, p_from_month date DEFAULT NULL::date, p_to_month date DEFAULT NULL::date) RETURNS TABLE(portfolio_id integer, portfolio_name character varying, month date, period_start date, period_end date, start_value numeric, end_value numeric, net_flow numeric, portfolio_return_pct numeric, spx_return_pct numeric, excess_return_pct numeric, cum_portfolio_pct numeric, cum_spx_pct numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH params AS (
        -- Last month to compute: p_to_month's month, never after the current month
        SELECT LEAST(date_trunc('month', COALESCE(p_to_month, CURRENT_DATE)),
                     date_trunc('month', CURRENT_DATE))::date AS last_month
    ),
    pf AS (
        -- Chosen portfolios that have started, with the S&P base of the first month
        SELECT p.portfolio_id, p.portfolio_name, p.starting_cash, p.start_date,
               COALESCE(
                   (SELECT dp.close FROM daily_price dp          -- latest close before start_date
                    WHERE dp.ticker = '^GSPC' AND dp.price_date < p.start_date
                    ORDER BY dp.price_date DESC LIMIT 1),
                   (SELECT dp.open FROM daily_price dp           -- fallback: first open from start_date
                    WHERE dp.ticker = '^GSPC' AND dp.price_date >= p.start_date
                    ORDER BY dp.price_date LIMIT 1)) AS spx_base
        FROM portfolio p
        WHERE p.start_date <= CURRENT_DATE
          AND (p_portfolio_id IS NULL OR p.portfolio_id = p_portfolio_id)
    ),
    months AS (
        -- One row per portfolio and month, from start_date's month to last_month
        SELECT pf.portfolio_id, m::date AS month,
               GREATEST(m::date, pf.start_date)                          AS period_start,
               LEAST((m + INTERVAL '1 month - 1 day')::date, CURRENT_DATE) AS period_end
        FROM pf
        CROSS JOIN params
        CROSS JOIN LATERAL generate_series(date_trunc('month', pf.start_date),
                                           params.last_month,
                                           INTERVAL '1 month') AS m
    ),
    events AS (
        -- Every cash transaction (event_order 0) and trade (1), once per portfolio
        SELECT pf.portfolio_id, h.event_date, h.event_order, h.ticker,
               h.cash_delta, h.share_delta
        FROM pf
        CROSS JOIN LATERAL fn_portfolio_history(pf.portfolio_id) h
    ),
    month_cash AS (
        -- Cash at period_end, net flow and weighted flow inside the period
        SELECT m.portfolio_id, m.month,
               pf.starting_cash + COALESCE(SUM(e.cash_delta), 0) AS cash_end,
               COALESCE(SUM(e.cash_delta)
                        FILTER (WHERE e.event_order = 0 AND e.event_date >= m.period_start), 0)
                   AS net_flow,
               COALESCE(SUM(e.cash_delta * (m.period_end - e.event_date + 1)
                                         / (m.period_end - m.period_start + 1))
                        FILTER (WHERE e.event_order = 0 AND e.event_date >= m.period_start), 0)
                   AS weighted_flow
        FROM months m
        JOIN pf ON pf.portfolio_id = m.portfolio_id
        LEFT JOIN events e ON e.portfolio_id = m.portfolio_id
                          AND e.event_date <= m.period_end
        GROUP BY m.portfolio_id, m.month, pf.starting_cash
    ),
    month_positions AS (
        -- Shares of each ticker held at period_end
        SELECT m.portfolio_id, m.month, m.period_end, e.ticker,
               SUM(e.share_delta) AS shares
        FROM months m
        JOIN events e ON e.portfolio_id = m.portfolio_id
                     AND e.event_date <= m.period_end
                     AND e.ticker IS NOT NULL
        GROUP BY m.portfolio_id, m.month, m.period_end, e.ticker
        HAVING SUM(e.share_delta) > 0
    ),
    month_stock AS (
        SELECT mp.portfolio_id, mp.month, SUM(mp.shares * c.close) AS stock_value
        FROM month_positions mp
        -- Latest close on or before period_end (primary key index)
        CROSS JOIN LATERAL (
            SELECT dp.close FROM daily_price dp
            WHERE dp.ticker = mp.ticker AND dp.price_date <= mp.period_end
            ORDER BY dp.price_date DESC
            LIMIT 1
        ) c
        GROUP BY mp.portfolio_id, mp.month
    ),
    monthly AS (
        SELECT m.portfolio_id, pf.portfolio_name, m.month, m.period_start, m.period_end,
               -- LAG = the previous row's value in the window (previous month)
               COALESCE(LAG(mc.cash_end + COALESCE(ms.stock_value, 0)) OVER w,
                        pf.starting_cash)                    AS start_value,
               mc.cash_end + COALESCE(ms.stock_value, 0)     AS end_value,
               mc.net_flow, mc.weighted_flow,
               COALESCE(LAG(spx.close) OVER w, pf.spx_base)  AS spx_start,
               spx.close                                     AS spx_end
        FROM months m
        JOIN pf              ON pf.portfolio_id = m.portfolio_id
        JOIN month_cash mc   ON mc.portfolio_id = m.portfolio_id AND mc.month = m.month
        LEFT JOIN month_stock ms ON ms.portfolio_id = m.portfolio_id AND ms.month = m.month
        -- Latest ^GSPC close on or before period_end (primary key index)
        LEFT JOIN LATERAL (
            SELECT dp.close FROM daily_price dp
            WHERE dp.ticker = '^GSPC' AND dp.price_date <= m.period_end
            ORDER BY dp.price_date DESC
            LIMIT 1
        ) spx ON true
        WINDOW w AS (PARTITION BY m.portfolio_id ORDER BY m.month)
    ),
    returns AS (
        -- The from-month filter must come AFTER the LAG above (a WHERE in
        -- the same SELECT runs before window functions, and the first
        -- shown month would lose its start_value)
        SELECT mo.*,
               (mo.end_value - mo.start_value - mo.net_flow)
                   / NULLIF(mo.start_value + mo.weighted_flow, 0) AS r_p,
               mo.spx_end / NULLIF(mo.spx_start, 0) - 1           AS r_spx
        FROM monthly mo
        WHERE p_from_month IS NULL OR mo.month >= date_trunc('month', p_from_month)
    )
    SELECT r.portfolio_id, r.portfolio_name, r.month, r.period_start, r.period_end,
           r.start_value, r.end_value, r.net_flow,
           ROUND(100 * r.r_p, 2),
           ROUND(100 * r.r_spx, 2),
           ROUND(100 * (r.r_p - r.r_spx), 2),
           -- Compounded: (1+r1)(1+r2)... - 1 = EXP(LN(1+r1) + LN(1+r2) + ...) - 1,
           -- a running SUM because PostgreSQL has no product aggregate
           ROUND(100 * (EXP(SUM(LN(CASE WHEN 1 + r.r_p   > 0 THEN 1 + r.r_p   END)) OVER c) - 1), 2),
           ROUND(100 * (EXP(SUM(LN(CASE WHEN 1 + r.r_spx > 0 THEN 1 + r.r_spx END)) OVER c) - 1), 2)
    FROM returns r
    WINDOW c AS (PARTITION BY r.portfolio_id ORDER BY r.month ROWS UNBOUNDED PRECEDING)
    ORDER BY r.portfolio_id, r.month;
$$;


--
-- Name: fn_portfolio_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_portfolio_history(p_portfolio_id integer) RETURNS TABLE(event_date date, event_order integer, event_id integer, event_label text, ticker character varying, cash_delta numeric, share_delta integer, cash_after numeric, shares_after bigint)
    LANGUAGE sql STABLE
    AS $$
    WITH events AS (
        SELECT c.txn_date    AS event_date,
               0             AS event_order,
               c.cash_txn_id AS event_id,
               format('cash transaction %s (%s %s)',
                      c.cash_txn_id, c.txn_type, c.amount) AS event_label,
               NULL::VARCHAR(10) AS ticker,
               CASE c.txn_type WHEN 'DEPOSIT' THEN c.amount ELSE -c.amount END AS cash_delta,
               0             AS share_delta
        FROM cash_transaction c
        WHERE c.portfolio_id = p_portfolio_id

        UNION ALL

        SELECT t.trade_date,
               1,
               t.trade_id,
               format('trade %s (%s %s %s @ %s)',
                      t.trade_id, t.trade_type, t.shares, t.ticker, t.price),
               t.ticker,
               -- BUY spends cash and adds shares; SELL does the opposite
               CASE t.trade_type WHEN 'BUY' THEN -(t.shares * t.price) ELSE t.shares * t.price END,
               CASE t.trade_type WHEN 'BUY' THEN t.shares ELSE -t.shares END
        FROM trade t
        WHERE t.portfolio_id = p_portfolio_id
    )
    SELECT e.event_date, e.event_order, e.event_id, e.event_label, e.ticker,
           e.cash_delta, e.share_delta,
           p.starting_cash + SUM(e.cash_delta) OVER w_all    AS cash_after,
           SUM(e.share_delta)                  OVER w_ticker AS shares_after
    FROM events e
    JOIN portfolio p ON p.portfolio_id = p_portfolio_id
    -- ROWS UNBOUNDED PRECEDING = running total from the first row up to
    -- and including the current row, in the history order
    WINDOW w_all    AS (ORDER BY e.event_date, e.event_order, e.event_id
                        ROWS UNBOUNDED PRECEDING),
           w_ticker AS (PARTITION BY e.ticker
                        ORDER BY e.event_date, e.event_order, e.event_id
                        ROWS UNBOUNDED PRECEDING)
    ORDER BY e.event_date, e.event_order, e.event_id;
$$;


--
-- Name: fn_portfolio_history_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_portfolio_history_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_portfolio_id  INTEGER;
BEGIN
    -- On DELETE there is no NEW row, only OLD
    IF TG_OP = 'DELETE' THEN
        v_portfolio_id := OLD.portfolio_id;
    ELSE
        v_portfolio_id := NEW.portfolio_id;
    END IF;

    -- Lock again (no-op if this transaction already holds it).
    -- UPDATE/DELETE have no BEFORE lock, so this is their lock.
    PERFORM 1 FROM portfolio WHERE portfolio_id = v_portfolio_id FOR UPDATE;

    -- Portfolio already gone: this row is part of a cascade delete
    -- (portfolio or investor deleted). Nothing left to check.
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    PERFORM fn_check_portfolio_history(v_portfolio_id);
    RETURN NULL;   -- return value of an AFTER trigger is ignored
END;
$$;


--
-- Name: fn_position_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_position_history(p_portfolio_id integer) RETURNS TABLE(ticker character varying, trade_seq bigint, trade_id integer, trade_date date, trade_type character varying, shares integer, price numeric, shares_after bigint, avg_cost_after numeric, realized_pl numeric, realized_pl_total numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH RECURSIVE ordered AS (
        -- Number each ticker's trades in history order
        SELECT t.ticker,
               ROW_NUMBER() OVER (PARTITION BY t.ticker
                                  ORDER BY t.trade_date, t.trade_id) AS seq,
               t.trade_id, t.trade_date, t.trade_type, t.shares, t.price
        FROM trade t
        WHERE t.portfolio_id = p_portfolio_id
    ),
    walk AS (
        -- Anchor: an empty position (seq 0) for each ticker.
        -- Explicit casts: both halves of a recursive UNION must have
        -- exactly the same column types.
        SELECT DISTINCT o.ticker,
               0::BIGINT            AS seq,
               NULL::INTEGER        AS trade_id,
               NULL::DATE           AS trade_date,
               NULL::VARCHAR(4)     AS trade_type,
               NULL::INTEGER        AS shares,
               NULL::NUMERIC(12,2)  AS price,
               0::BIGINT            AS shares_after,
               0::NUMERIC           AS avg_cost_after,
               0::NUMERIC           AS realized_pl,
               0::NUMERIC           AS realized_pl_total
        FROM ordered o

        UNION ALL

        -- Recursive step: apply trade number seq + 1 to the previous state w
        SELECT o.ticker, o.seq, o.trade_id, o.trade_date, o.trade_type, o.shares, o.price,
               CASE o.trade_type
                    WHEN 'BUY' THEN w.shares_after + o.shares
                    ELSE            w.shares_after - o.shares
               END,
               CASE o.trade_type
                    WHEN 'BUY' THEN (w.shares_after * w.avg_cost_after + o.shares * o.price)
                                    / (w.shares_after + o.shares)
                    ELSE            w.avg_cost_after
               END,
               CASE o.trade_type
                    WHEN 'SELL' THEN o.shares * (o.price - w.avg_cost_after)
                    ELSE             0
               END,
               w.realized_pl_total
                 + CASE o.trade_type
                        WHEN 'SELL' THEN o.shares * (o.price - w.avg_cost_after)
                        ELSE             0
                   END
        FROM walk w
        JOIN ordered o ON o.ticker = w.ticker
                      AND o.seq    = w.seq + 1
    )
    SELECT w.ticker, w.seq, w.trade_id, w.trade_date, w.trade_type, w.shares, w.price,
           w.shares_after, w.avg_cost_after, w.realized_pl, w.realized_pl_total
    FROM walk w
    WHERE w.seq > 0                    -- drop the empty anchor rows
    ORDER BY w.ticker, w.seq;
$$;


--
-- Name: fn_sector_allocation(integer, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_sector_allocation(p_portfolio_id integer DEFAULT NULL::integer, p_as_of date DEFAULT NULL::date, p_include_cash boolean DEFAULT true) RETURNS TABLE(portfolio_id integer, portfolio_name character varying, as_of date, sector_name character varying, market_value numeric, pct numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH params AS (
        SELECT COALESCE(p_as_of, CURRENT_DATE) AS as_of
    ),
    pf AS (
        -- Portfolios that exist on as_of (simulation already started)
        SELECT p.portfolio_id, p.portfolio_name, p.starting_cash, params.as_of
        FROM portfolio p CROSS JOIN params
        WHERE p.start_date <= params.as_of
          AND (p_portfolio_id IS NULL OR p.portfolio_id = p_portfolio_id)
    ),
    positions AS (
        -- Shares held on as_of: a plain SUM is fine (order doesn't matter for shares)
        SELECT t.portfolio_id, t.ticker,
               SUM(CASE t.trade_type WHEN 'BUY' THEN t.shares ELSE -t.shares END) AS shares
        FROM trade t
        JOIN pf ON pf.portfolio_id = t.portfolio_id
        WHERE t.trade_date <= pf.as_of
        GROUP BY t.portfolio_id, t.ticker
        HAVING SUM(CASE t.trade_type WHEN 'BUY' THEN t.shares ELSE -t.shares END) > 0
    ),
    stock_values AS (
        SELECT pos.portfolio_id,
               COALESCE(sec.sector_name, 'Unclassified')::VARCHAR(50) AS sector_name,
               SUM(pos.shares * c.close) AS market_value
        FROM positions pos
        JOIN pf          ON pf.portfolio_id = pos.portfolio_id
        JOIN stock s     ON s.ticker = pos.ticker
        LEFT JOIN sector sec ON sec.sector_id = s.sector_id
        -- Latest close on or before as_of (uses the primary key).
        -- A held ticker always has one: it was traded on a priced day <= as_of.
        CROSS JOIN LATERAL (
            SELECT dp.close FROM daily_price dp
            WHERE dp.ticker = pos.ticker AND dp.price_date <= pf.as_of
            ORDER BY dp.price_date DESC
            LIMIT 1
        ) c
        GROUP BY pos.portfolio_id, COALESCE(sec.sector_name, 'Unclassified')
    ),
    cash AS (
        -- Cash on as_of = running cash after the last event on or before as_of
        SELECT pf.portfolio_id,
               'Cash'::VARCHAR(50) AS sector_name,
               COALESCE(h.cash_after, pf.starting_cash) AS market_value
        FROM pf
        LEFT JOIN LATERAL (
            SELECT h.cash_after FROM fn_portfolio_history(pf.portfolio_id) h
            WHERE h.event_date <= pf.as_of
            ORDER BY h.event_date DESC, h.event_order DESC, h.event_id DESC
            LIMIT 1
        ) h ON true
        WHERE p_include_cash
    ),
    all_rows AS (
        SELECT * FROM stock_values
        UNION ALL
        SELECT * FROM cash
    )
    SELECT r.portfolio_id, pf.portfolio_name, pf.as_of, r.sector_name, r.market_value,
           -- window SUM: the portfolio's total value, next to every row
           ROUND(100 * r.market_value
                 / NULLIF(SUM(r.market_value) OVER (PARTITION BY r.portfolio_id), 0), 2) AS pct
    FROM all_rows r
    JOIN pf ON pf.portfolio_id = r.portfolio_id
    ORDER BY r.portfolio_id, (r.sector_name = 'Cash'), r.market_value DESC, r.sector_name;
$$;


--
-- Name: fn_top_movers(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_top_movers(p_start date, p_end date DEFAULT NULL::date, p_limit integer DEFAULT 5) RETURNS TABLE(direction text, rank bigint, ticker character varying, company_name character varying, start_date date, start_close numeric, end_date date, end_close numeric, pct_change numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH params AS (
        SELECT p_start AS start_d,
               COALESCE(p_end, CURRENT_DATE) AS end_d
    ),
    moves AS (
        SELECT s.ticker, s.company_name,
               f.price_date AS start_date, f.close AS start_close,
               l.price_date AS end_date,   l.close AS end_close,
               (l.close - f.close) / f.close AS change      -- exact, used for ranking
        FROM stock s
        CROSS JOIN params
        -- first close in the period (primary key index: ticker, price_date)
        CROSS JOIN LATERAL (
            SELECT dp.price_date, dp.close FROM daily_price dp
            WHERE dp.ticker = s.ticker AND dp.price_date BETWEEN params.start_d AND params.end_d
            ORDER BY dp.price_date
            LIMIT 1
        ) f
        -- last close in the period
        CROSS JOIN LATERAL (
            SELECT dp.price_date, dp.close FROM daily_price dp
            WHERE dp.ticker = s.ticker AND dp.price_date BETWEEN params.start_d AND params.end_d
            ORDER BY dp.price_date DESC
            LIMIT 1
        ) l
        WHERE s.security_type = 'STOCK'
          AND l.price_date > f.price_date      -- need two different days
    ),
    ranked AS (
        SELECT 'GAINER' AS direction, RANK() OVER (ORDER BY m.change DESC) AS rnk, m.*
        FROM moves m WHERE m.change > 0
        UNION ALL
        SELECT 'LOSER', RANK() OVER (ORDER BY m.change ASC), m.*
        FROM moves m WHERE m.change < 0
    )
    SELECT r.direction, r.rnk, r.ticker, r.company_name,
           r.start_date, r.start_close, r.end_date, r.end_close,
           ROUND(100 * r.change, 2) AS pct_change
    FROM ranked r
    WHERE r.rnk <= p_limit
    ORDER BY r.direction, r.rnk, r.ticker;
$$;


