--
-- Name: fn_trade_no_truncate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_trade_no_truncate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'trade cannot be truncated'
        USING ERRCODE    = 'check_violation',
              CONSTRAINT = 'trg_trade_no_truncate',
              HINT       = 'Use db/reset.sql to rebuild the database.';

END;
$$;


--
-- Name: fn_trade_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_trade_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_security_type  stock.security_type%TYPE;
    v_low            daily_price.low%TYPE;
    v_high           daily_price.high%TYPE;
BEGIN
    -- -----------------------------------------------------------------
    -- (c) UPDATE may change only shares and price
    -- -----------------------------------------------------------------
    IF TG_OP = 'UPDATE' THEN
        IF (NEW.portfolio_id, NEW.trade_type, NEW.trade_date)
           IS DISTINCT FROM
           (OLD.portfolio_id, OLD.trade_type, OLD.trade_date) THEN
            RAISE EXCEPTION 'Only shares and price of a trade can be changed'
                USING ERRCODE    = 'check_violation',
                      CONSTRAINT = 'trg_trade_immutable_cols',
                      DETAIL     = format('Trade %s: portfolio, type and date are fixed.',
                                          OLD.trade_id),
                      HINT       = 'Delete the trade and enter a new one instead.';
        END IF;

        -- A ticker change is allowed only as part of a stock rename
        -- (ON UPDATE CASCADE from stock -> daily_price -> trade).
        -- During a rename the old ticker no longer exists in stock;
        -- in a direct UPDATE of trade it still does.
        IF NEW.ticker IS DISTINCT FROM OLD.ticker
           AND EXISTS (SELECT 1 FROM stock WHERE ticker = OLD.ticker) THEN
            RAISE EXCEPTION 'Only shares and price of a trade can be changed'
                USING ERRCODE    = 'check_violation',
                      CONSTRAINT = 'trg_trade_immutable_cols',
                      DETAIL     = format('Trade %s: ticker %s cannot be changed to %s.',
                                          OLD.trade_id, OLD.ticker, NEW.ticker),
                      HINT       = 'Delete the trade and enter a new one instead.';
        END IF;
    END IF;

    -- -----------------------------------------------------------------
    -- Look up the security type and that day's range in one query.
    -- LEFT JOIN: a stock with no price row that day still returns
    -- its security_type (with NULL low/high).
    -- -----------------------------------------------------------------
    SELECT s.security_type, dp.low, dp.high
      INTO v_security_type, v_low, v_high
      FROM stock s
      LEFT JOIN daily_price dp
             ON dp.ticker = s.ticker
            AND dp.price_date = NEW.trade_date
     WHERE s.ticker = NEW.ticker;

    -- Unknown ticker: leave it to fk_trade_daily_price
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    -- -----------------------------------------------------------------
    -- (b) no trading an INDEX
    -- -----------------------------------------------------------------
    IF v_security_type = 'INDEX' THEN
        RAISE EXCEPTION '% is an index and cannot be traded', NEW.ticker
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_trade_not_index',
                  HINT       = 'Indexes can be added to a watchlist, but not bought or sold.';
    END IF;

    -- -----------------------------------------------------------------
    -- (a) price within the day's low..high
    -- v_low IS NULL means no price row that day: leave it to the FK.
    -- NEW.price IS NULL: the NOT NULL constraint reports it.
    -- -----------------------------------------------------------------
    IF v_low IS NOT NULL AND NEW.price NOT BETWEEN v_low AND v_high THEN
        RAISE EXCEPTION 'Price % is outside the % range on %', NEW.price, NEW.ticker, NEW.trade_date
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'trg_trade_price_in_range',
                  DETAIL     = format('Allowed range: %s to %s.', v_low, v_high);
    END IF;

    RETURN NEW;   -- BEFORE trigger: returning NEW lets the row be written
END;
$$;


--
-- Name: fn_watchlist_targets_reached(integer, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_watchlist_targets_reached(p_investor_id integer DEFAULT NULL::integer, p_as_of date DEFAULT NULL::date) RETURNS TABLE(investor_id integer, investor_name character varying, watchlist_id integer, watchlist_name character varying, ticker character varying, target_price numeric, close_date date, latest_close numeric, pct_above_target numeric)
    LANGUAGE sql STABLE
    AS $$
    WITH params AS (
        SELECT COALESCE(p_as_of, CURRENT_DATE) AS as_of
    )
    SELECT i.investor_id, i.name, w.watchlist_id, w.watchlist_name,
           wi.ticker, wi.target_price, c.price_date, c.close,
           ROUND(100 * (c.close - wi.target_price) / wi.target_price, 2) AS pct_above_target
    FROM watchlist_item wi
    JOIN watchlist w ON w.watchlist_id = wi.watchlist_id
    JOIN investor i  ON i.investor_id  = w.investor_id
    CROSS JOIN params
    -- Latest close on or before as_of (primary key index)
    CROSS JOIN LATERAL (
        SELECT dp.price_date, dp.close FROM daily_price dp
        WHERE dp.ticker = wi.ticker AND dp.price_date <= params.as_of
        ORDER BY dp.price_date DESC
        LIMIT 1
    ) c
    WHERE c.close >= wi.target_price
      AND (p_investor_id IS NULL OR i.investor_id = p_investor_id)
    ORDER BY pct_above_target DESC, i.name, w.watchlist_name, wi.ticker;
$$;


--
-- Name: record_cash_transaction(integer, text, numeric, date, integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.record_cash_transaction(IN p_portfolio_id integer, IN p_txn_type text, IN p_amount numeric, IN p_txn_date date, INOUT p_cash_txn_id integer DEFAULT NULL::integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_txn_type  TEXT;
    v_missing   TEXT[];
BEGIN
    -- ' deposit ' -> 'DEPOSIT'; a blank string becomes NULL (= missing)
    v_txn_type := NULLIF(upper(btrim(p_txn_type)), '');

    v_missing := array_remove(ARRAY[
        CASE WHEN p_portfolio_id IS NULL THEN 'portfolio_id' END,
        CASE WHEN v_txn_type     IS NULL THEN 'txn_type'     END,
        CASE WHEN p_amount       IS NULL THEN 'amount'       END,
        CASE WHEN p_txn_date     IS NULL THEN 'txn_date'     END
    ], NULL);

    IF cardinality(v_missing) > 0 THEN
        RAISE EXCEPTION 'Missing cash transaction input: %', array_to_string(v_missing, ', ')
            USING ERRCODE    = 'check_violation',
                  CONSTRAINT = 'exec_missing_input',
                  DETAIL     = format('Missing: %s.', array_to_string(v_missing, ', '));
    END IF;

    VALUES (p_portfolio_id, v_txn_type, p_amount, p_txn_date)
    RETURNING cash_txn_id INTO p_cash_txn_id;
END;
$$;


