CREATE TABLE public.cash_transaction (
    cash_txn_id integer NOT NULL,
    portfolio_id integer NOT NULL,
    txn_type character varying(10) NOT NULL,
    amount numeric(14,2) NOT NULL,
    txn_date date NOT NULL,
    CONSTRAINT chk_cash_amount_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT chk_cash_deposit_cap CHECK ((((txn_type)::text <> 'DEPOSIT'::text) OR (amount <= (10000000)::numeric))),
    CONSTRAINT chk_cash_txn_type CHECK (((txn_type)::text = ANY ((ARRAY['DEPOSIT'::character varying, 'WITHDRAWAL'::character varying])::text[])))
);


