--
-- Name: v_cash_balance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cash_balance AS
 WITH cash_totals AS (
         SELECT cash_transaction.portfolio_id,
            sum(cash_transaction.amount) FILTER (WHERE ((cash_transaction.txn_type)::text = 'DEPOSIT'::text)) AS deposits,
            sum(cash_transaction.amount) FILTER (WHERE ((cash_transaction.txn_type)::text = 'WITHDRAWAL'::text)) AS withdrawals
           FROM public.cash_transaction
          GROUP BY cash_transaction.portfolio_id
        ), trade_totals AS (
         SELECT trade.portfolio_id,
            sum(((trade.shares)::numeric * trade.price)) FILTER (WHERE ((trade.trade_type)::text = 'BUY'::text)) AS buys,
            sum(((trade.shares)::numeric * trade.price)) FILTER (WHERE ((trade.trade_type)::text = 'SELL'::text)) AS sells
           FROM public.trade
          GROUP BY trade.portfolio_id
        )
 SELECT p.portfolio_id,
    p.investor_id,
    p.portfolio_name,
    p.starting_cash,
    COALESCE(c.deposits, (0)::numeric) AS deposits,
    COALESCE(c.withdrawals, (0)::numeric) AS withdrawals,
    COALESCE(t.buys, (0)::numeric) AS buys,
    COALESCE(t.sells, (0)::numeric) AS sells,
    ((((p.starting_cash + COALESCE(c.deposits, (0)::numeric)) - COALESCE(c.withdrawals, (0)::numeric)) - COALESCE(t.buys, (0)::numeric)) + COALESCE(t.sells, (0)::numeric)) AS cash_balance
   FROM ((public.portfolio p
     LEFT JOIN cash_totals c ON ((c.portfolio_id = p.portfolio_id)))
     LEFT JOIN trade_totals t ON ((t.portfolio_id = p.portfolio_id)));


--
-- Name: v_holdings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_holdings AS
 SELECT DISTINCT ON (p.portfolio_id, h.ticker) p.portfolio_id,
    h.ticker,
    h.shares_after AS shares_held,
        CASE
            WHEN (h.shares_after > 0) THEN round(h.avg_cost_after, 2)
            ELSE NULL::numeric
        END AS avg_cost,
        CASE
            WHEN (h.shares_after > 0) THEN round(((h.shares_after)::numeric * h.avg_cost_after), 2)
            ELSE (0)::numeric
        END AS cost_basis,
    round(h.realized_pl_total, 2) AS realized_pl,
    (h.shares_after > 0) AS is_open,
    h.trade_seq AS trade_count,
    h.trade_date AS last_trade_date
   FROM (public.portfolio p
     CROSS JOIN LATERAL public.fn_position_history(p.portfolio_id) h(ticker, trade_seq, trade_id, trade_date, trade_type, shares, price, shares_after, avg_cost_after, realized_pl, realized_pl_total))
  ORDER BY p.portfolio_id, h.ticker, h.trade_seq DESC;


